// Your first script: the drone plants grass, waits and harvests.
plant(Plant.GRASS);
move(Dir.EAST);
plant(Plant.GRASS);

// Grass takes a while to be ready.
wait(130);

// Harvest both cells. Ripe grass becomes hay.
harvest();
move(Dir.WEST);
harvest();

log("Hay in stock:", getStock(Item.HAY));
